-- ExamGrind verified daily current-affairs desk: 29 October 2026.
-- Every item below is independently checked against the linked competent official release.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-10-29-india-mexico-pta-negotiations$$, $$2026-10-29$$,
$$India and Mexico launch negotiations for a Preferential Trade Agreement$$,
$$India and Mexico signed Terms of Reference that formally launch negotiations for a Preferential Trade Agreement (PTA). The document sets the framework and roadmap for talks; it is not itself a concluded trade agreement.$$,
$$This is a clean international-trade distinction for prelims: a PTA is an agreement under which participating countries extend preferential treatment on selected trade, while signed Terms of Reference only begin the negotiating process.$$,
$$The announced negotiating scope includes market access for goods, rules of origin, customs procedures and trade facilitation, dispute settlement, sanitary and phytosanitary measures, technical barriers to trade and trade remedies. Students should avoid calling the PTA operational until negotiations conclude and both sides complete the necessary approval process.$$,
$$India and Mexico launch Negotiations for Preferential Trade Agreement, Sign Terms of Reference$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329303&lang=1&reg=3$$,
$$Ministry of Commerce and Industry / Press Information Bureau$$, $$2026-10-28$$,
$$["India and Mexico signed Terms of Reference to launch PTA negotiations.","The Terms of Reference set the framework, scope, modalities and roadmap for the negotiations.","The stated scope includes rules of origin, customs procedures, SPS measures and technical barriers to trade.","A PTA negotiation is not the same as a final trade agreement in force."]$$::jsonb,
$$[{"question":"What did India and Mexico sign on 28 October 2026?","answer":"Terms of Reference for negotiating a Preferential Trade Agreement, not the final PTA itself."}]$$::jsonb,
$${"title":"From trade talks to an agreement","steps":["Countries sign a negotiating framework.","Delegations negotiate market access and trade rules.","A final agreement is concluded and approved.","Preferential treatment takes effect only after entry into force."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-29-pm-vgsy-cabinet-approval$$, $$2026-10-29$$,
$$Cabinet approves Pradhan Mantri Viksit Gram Swaraj Yojana for grassroots governance$$,
$$The Union Cabinet approved Pradhan Mantri Viksit Gram Swaraj Yojana (PM VGSY) as a Centrally Sponsored Scheme for 2026–27 to 2030–31, with an outlay of Rs 7,395.55 crore. It is intended to strengthen participatory planning, digital integration and accountability in Panchayats.$$,
$$The scheme is directly relevant to Panchayati Raj, cooperative federalism and local-development planning. It also distinguishes a Centrally Sponsored Scheme, implemented with State participation, from a wholly Central Sector Scheme.$$,
$$The release says the scheme will cover all States and Union Territories, including eligible traditional rural local-government institutions in areas outside Part IX where Panchayats do not exist. It proposes use of eGramSwaraj for Gram Panchayat Development Plans and AuditOnline for audit planning; these are governance tools, not newly created constitutional bodies.$$,
$$Cabinet approves Pradhan Mantri Viksit Gram Swaraj Yojana as a Centrally Sponsored Scheme for 2026-27 to 2030-31$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329483&lang=1&reg=3$$,
$$Ministry of Panchayati Raj / Press Information Bureau$$, $$2026-10-28$$,
$$["PM VGSY is approved as a Centrally Sponsored Scheme for 2026–27 to 2030–31.","Its total outlay is Rs 7,395.55 crore, with separate Central and State shares.","It uses eGramSwaraj for Gram Panchayat Development Plans and AuditOnline for audit plans.","It extends to eligible traditional local bodies in non-Part IX areas as well as Panchayats."]$$::jsonb,
$$[{"question":"Which portals are identified for planning and audit under PM VGSY?","answer":"eGramSwaraj for Gram Panchayat Development Plans and AuditOnline for audit plans."}]$$::jsonb,
$${"title":"Grassroots-governance loop","steps":["Gram Sabha and Panchayat identify local priorities.","A development plan is prepared through the digital system.","Departments and resources are aligned for implementation.","Online audit planning and disclosure support accountability."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-29-container-manufacturing-promotion-scheme$$, $$2026-10-29$$,
$$Cabinet approves Container Manufacturing Promotion Scheme$$,
$$The Union Cabinet approved the Container Manufacturing Promotion Scheme (CMPS), with a Rs 10,000 crore budgetary outlay through FY 2039–40, to build domestic container-manufacturing capacity and strengthen maritime-logistics resilience.$$,
$$This joins industrial policy with trade logistics. For exams, remember that TEU is a standard container-capacity unit and that the scheme addresses manufacturing of shipping containers, not operation of a shipping line.$$,
$$CMPS has three principal assistance streams: interest subvention on eligible term loans, operational-expenditure assistance for qualifying containers made to global shipping standards, and testing/certification assistance. The official release estimates annual domestic capacity could rise to about 7.5 lakh TEUs; this is a programme target, not current production.$$,
$$Cabinet approves Container Manufacturing Promotion Scheme$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329488&lang=1&reg=3$$,
$$Ministry of Ports, Shipping and Waterways / Press Information Bureau$$, $$2026-10-28$$,
$$["CMPS has a Rs 10,000 crore budgetary outlay through FY 2039–40.","TEU means Twenty-foot Equivalent Unit, a standard measure of container capacity.","The scheme includes interest subvention, operational-expenditure assistance, and testing/certification support.","Its stated purpose is to reduce import dependence and build a domestic container-manufacturing ecosystem."]$$::jsonb,
$$[{"question":"What does TEU measure in the context of CMPS?","answer":"Twenty-foot Equivalent Units, the standard capacity measure used for shipping containers."}]$$::jsonb,
$${"title":"Container-manufacturing support","steps":["Manufacturers establish or expand eligible facilities.","Capital-loan support lowers financing costs.","Production support helps bridge competitiveness gaps.","Testing and certification support access to global standards."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-29-khelo-india-sports-goods-manufacturing$$, $$2026-10-29$$,
$$Cabinet clears Khelo India Sports Goods Manufacturing Scheme$$,
$$The Union Cabinet approved the Khelo India Sports Goods Manufacturing Scheme, with an outlay of Rs 1,856.67 crore for 2026–27 to 2033–34. The scheme combines manufacturing incentives with cluster, certification, innovation and skills support for the sports-goods sector.$$,
$$It is an example of sector-specific industrial policy. The useful exam distinction is between the existing Khelo India sports-development initiative and this new manufacturing-focused scheme, which also links to Make in India and export competitiveness.$$,
$$The scheme envisages dedicated Sports Goods Manufacturing Zones developed through convergence with BHAVYA and NICDC industrial infrastructure. Its investment/turnover support component has a combined outlay of Rs 1,130 crore, while a separate allocation supports international-sports-federation certification; projected benefits are not automatic entitlements.$$,
$$Cabinet approves Khelo India Sports Goods Manufacturing Scheme for Building a Globally Competitive Sports Manufacturing Ecosystem$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329481&lang=1&reg=1$$,
$$Ministry of Youth Affairs and Sports / Press Information Bureau$$, $$2026-10-28$$,
$$["The scheme's outlay is Rs 1,856.67 crore for 2026–27 to 2033–34.","It proposes dedicated Sports Goods Manufacturing Zones.","BHAVYA and NICDC industrial parks are identified for infrastructure convergence.","The scheme supports investment, production, certification, innovation, skilling and market development."]$$::jsonb,
$$[{"question":"Is the Khelo India Sports Goods Manufacturing Scheme only an athlete-training programme?","answer":"No. It is a manufacturing-ecosystem scheme for sports goods, with incentives and cluster-related support."}]$$::jsonb,
$${"title":"Sports goods value chain","steps":["Manufacturing zones co-locate firms and suppliers.","Investment and turnover support expands production.","Testing, design and certification improve quality.","Skills and market-development support strengthen competitiveness."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-29-da-dr-additional-instalment$$, $$2026-10-29$$,
$$Cabinet approves additional Dearness Allowance and Dearness Relief instalment$$,
$$The Union Cabinet approved an additional 3 percentage-point instalment of Dearness Allowance for Central Government employees and Dearness Relief for pensioners, effective 1 July 2026. The release describes it as an increase over the existing rate of 60% of basic pay or pension.$$,
$$This is a public-finance and social-security recall item. It tests the difference between DA for serving Central Government employees and DR for pensioners, and why both are linked to compensation for price rise.$$,
$$The release estimates an annual exchequer impact of Rs 10,016.10 crore and says the increase follows the accepted formula based on recommendations of the Seventh Central Pay Commission. It does not mean that basic pay or basic pension rises by 3%; the approved addition applies to the allowance/relief rate.$$,
$$Cabinet approves Dearness Allowance to Central Government employees and Dearness Relief to Pensioners$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329485&lang=1&reg=3$$,
$$Ministry of Finance / Press Information Bureau$$, $$2026-10-28$$,
$$["DA is paid to Central Government employees and DR to pensioners.","The approved additional instalment is 3 percentage points, effective 1 July 2026.","The release refers to an existing rate of 60% of basic pay or pension.","The accepted formula is based on Seventh Central Pay Commission recommendations."]$$::jsonb,
$$[{"question":"Who receives Dearness Relief rather than Dearness Allowance?","answer":"Pensioners; Dearness Allowance applies to serving Central Government employees."}]$$::jsonb,
$${"title":"Inflation-compensation distinction","steps":["Price movement informs the accepted formula.","Government approves an allowance-rate revision.","Serving employees receive DA on basic pay.","Pensioners receive DR on basic pension."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-29-clean-sport-toolkit-unesco-mou$$, $$2026-10-29$$,
$$India and UNESCO sign MoU for a classroom clean-sport toolkit$$,
$$The Ministries of Youth Affairs and Sports and Education, with UNESCO, exchanged an MoU to take the Sports Values in Every Classroom Toolkit to schools. The initiative is intended to bring values such as integrity, fairness and respect into education and sporting activity.$$,
$$The agreement connects sport governance, education and anti-doping values. It is useful for distinguishing the National Anti-Doping Agency (NADA) India from UNESCO, an intergovernmental organisation that works on international cooperation in education, science and culture.$$,
$$The MoU was exchanged at NADA India's Clean Sport Conclave. The release presents the toolkit as an educational initiative; it does not replace anti-doping testing, disciplinary procedures or the legal framework governing prohibited substances.$$,
$$Sports and Education Ministries sign historic MoU with UNESCO to take clean sport values to every classroom$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329464&lang=1&reg=3$$,
$$Ministry of Youth Affairs and Sports / Press Information Bureau$$, $$2026-10-28$$,
$$["The MoU involves the Sports Ministry, Education Ministry and UNESCO.","It supports the Sports Values in Every Classroom Toolkit.","The exchange took place at NADA India's Clean Sport Conclave.","The stated values include respect, integrity and fairness."]$$::jsonb,
$$[{"question":"Which Indian agency is associated with the Clean Sport Conclave mentioned in the release?","answer":"The National Anti-Doping Agency (NADA) India."}]$$::jsonb,
$${"title":"Clean-sport ecosystem","steps":["International and national bodies frame values and standards.","A classroom toolkit introduces values through education.","Schools and sport settings reinforce fair-play norms.","Anti-doping testing and enforcement remain separate functions."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-29-pmegp-margin-money-subsidy$$, $$2026-10-29$$,
$$PMEGP receives a Rs 1,000 crore margin-money subsidy tranche$$,
$$The Ministry of MSME reported release of Rs 1,000 crore in margin-money subsidy under the Prime Minister's Employment Generation Programme (PMEGP). The release says the tranche supports 11,333 beneficiaries whose bank-sanctioned project loans total about Rs 3,260 crore.$$,
$$PMEGP is a frequently tested self-employment programme. This update helps distinguish a margin-money subsidy, which reduces the beneficiary's contribution or supports project financing under scheme rules, from the full bank loan amount.$$,
$$The official release associates the tranche with new micro enterprises and expected employment generation, especially in rural areas and among groups such as women, SCs and STs. These are programme outcomes and projections, not a guarantee that every applicant receives a subsidy or a loan.$$,
$$Union Minister for MSME releases Rs 1,000 Crore Margin Money Subsidy under PMEGP to support 11,333 new Micro Enterprises across India$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329819&lang=1&reg=3$$,
$$Ministry of Micro, Small and Medium Enterprises / Press Information Bureau$$, $$2026-10-28$$,
$$["PMEGP stands for Prime Minister's Employment Generation Programme.","The reported tranche is Rs 1,000 crore in margin-money subsidy.","The release links it to 11,333 beneficiaries and about Rs 3,260 crore in bank-sanctioned project loans.","PMEGP promotes self-employment through support for micro enterprises."]$$::jsonb,
$$[{"question":"Does the Rs 1,000 crore figure represent the total bank credit in this PMEGP release?","answer":"No. It is margin-money subsidy; the release separately reports approximately Rs 3,260 crore in bank-sanctioned project loans."}]$$::jsonb,
$${"title":"PMEGP financing logic","steps":["An eligible entrepreneur proposes a micro-enterprise project.","A bank sanctions project finance under scheme procedures.","Margin-money subsidy supports the financing structure.","The enterprise is established and expected to create livelihoods."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-29-gyan-bharatam-bnf-manuscript-mou$$, $$2026-10-29$$,
$$Culture Ministry and France's national library sign manuscript-preservation MoU$$,
$$India's Ministry of Culture and the Bibliothèque nationale de France (BnF) signed an MoU under the Gyan Bharatam Mission for cooperation on Indic-origin manuscript and documentary heritage. The stated areas include digitisation, digital access, conservation, technology exchange and research.$$,
$$The development is useful for culture and international-cooperation questions. It identifies BnF as France's national library and shows that preservation agreements can cover both physical conservation and digital access.$$,
$$The MoU was signed in Paris on 26 October and announced by PIB on 27 October. It is a cooperation arrangement, not a transfer of manuscript ownership or a declaration that every identified manuscript has already been digitised.$$,
$$Ministry of Culture signs MoU with Bibliothèque nationale de France to strengthen preservation of India's manuscript heritage$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2329163&lang=1&reg=6$$,
$$Ministry of Culture / Press Information Bureau$$, $$2026-10-27$$,
$$["BnF is the Bibliothèque nationale de France, France's national library.","The MoU is under the Gyan Bharatam Mission.","It covers digitisation, digital access, conservation, technology exchange and research.","It concerns Indic-origin manuscript and documentary heritage."]$$::jsonb,
$$[{"question":"What does BnF denote in the India–France manuscript-preservation MoU?","answer":"Bibliothèque nationale de France, the National Library of France."}]$$::jsonb,
$${"title":"Heritage-preservation partnership","steps":["Institutions identify and document relevant heritage.","Conservation safeguards physical material.","Digitisation improves research and access.","Technology and scholarly cooperation strengthen long-term preservation."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-29-tdb-manastu-green-propulsion-rdi$$, $$2026-10-29$$,
$$Technology Development Board backs indigenous green space propulsion$$,
$$The Technology Development Board (TDB), under the Department of Science and Technology, signed an agreement with Manastu Space Technologies for Rs 116 crore of support under the Research, Development and Innovation Fund. The project concerns a scalable green-propulsion system for satellites and launch vehicles.$$,
$$This is a science-and-technology item with a precise institutional hook: TDB supports commercialisation and deployment-oriented technology development, while Technology Readiness Levels indicate the maturity of a technology rather than its commercial success.$$,
$$The official release says the project aims to advance the propulsion system from TRL-6 to TRL-9, with an integrated thrust range of 5 mN to 300 N. It describes a hydrogen-peroxide-based propellant system; students should not infer that it is an ISRO launch approval or a completed, universally deployed technology.$$,
$$TDB-DST signs agreement with Manastu Space for Rs 116 crore RDI support to advance indigenous green propulsion technology$$,
$$https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2328399&lang=2&reg=48$$,
$$Technology Development Board, Department of Science and Technology / Press Information Bureau$$, $$2026-10-26$$,
$$["TDB is the Technology Development Board under the Department of Science and Technology.","The RDI support is Rs 116 crore for an indigenous green-propulsion project.","The project aims to move from Technology Readiness Level 6 to Level 9.","The propulsion system is intended for satellites and launch vehicles."]$$::jsonb,
$$[{"question":"What do TRL-6 and TRL-9 describe in this project?","answer":"Technology Readiness Levels, indicating progression from an advanced demonstration stage toward an operationally proven system."}]$$::jsonb,
$${"title":"From propulsion concept to deployment","steps":["A technology is demonstrated at an advanced readiness stage.","RDI support funds engineering, integration and validation.","Testing raises performance and reliability evidence.","A mature system can move toward wider deployment."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-10-29-india-mexico-pta-negotiations$$,
$$2026-10-29-pm-vgsy-cabinet-approval$$,
$$2026-10-29-container-manufacturing-promotion-scheme$$,
$$2026-10-29-khelo-india-sports-goods-manufacturing$$,
$$2026-10-29-da-dr-additional-instalment$$,
$$2026-10-29-clean-sport-toolkit-unesco-mou$$,
$$2026-10-29-pmegp-margin-money-subsidy$$,
$$2026-10-29-gyan-bharatam-bnf-manuscript-mou$$,
$$2026-10-29-tdb-manastu-green-propulsion-rdi$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
